INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (313807, 13880, 'South China Morning Post', 'en', 'UK nurses report ‘inhumane’ heat in hospitals as heatwave grips country', 'https://www.scmp.com/news/world/europe/article/3363844/uk-nurses-report-inhumane-heat-hospitals-heatwave-grips-country', 'Nurses are collapsing at work as they endure extreme heat in buildings that are proving unfit for the record temperatures gripping Britain. Conditions are “inhumane”, the Royal College of Nursing said on Thursday. Members have reported temperatures in excess of 30 degrees Celsius (86 degrees Fahrenheit) in UK hospital wards and care homes, often without access to air conditioning, fans or even to windows that open, the RCN said. As Britain sweats through its fifth heatwave of the year, record...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/80ed0914-0dd9-4dbb-9d83-3f867a39c325_b259e4cb.jpg?itok=LVdMcRui&v=1786591418', '2026-08-13T03:23:42+00:00', '2026-08-13T03:40:32.551384'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
