INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317503, 13880, 'The Guardian', 'en', 'Europe heatwave live: Temperatures of 40C expected in Spain, with amber heat health warning in place across large parts of UK', 'https://www.theguardian.com/environment/live/2026/aug/13/europe-heatwave-france-spain-italy-uk-degrees-temperature-record-summer-drought-latest-news-updates', 'In France, 80 departments have been placed on an orange heat warning Well, that was quick. Straight off the back of the solar eclipse last night, we’re heading into a solar inferno as extreme heat returns today, with temperatures above 40C in parts of Spain and up to 38C in London and Paris. Continue reading...', 'https://i.guim.co.uk/img/media/c8ac626264763f988ad635ecde75279c8b213b8d/889_0_2886_2309/master/2886.jpg?width=140&quality=85&auto=format&fit=max&s=21952f333de41ec00d98bafccd689e56', '2026-08-13T07:58:26+00:00', '2026-08-13T08:14:53.679813'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
