INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (322765, 13880, 'Le Monde', 'en', '''What will we have left if we stop loving summer?'': Heatwaves crush France''s season of insouciance', 'https://www.lemonde.fr/en/environment/article/2026/08/13/what-will-we-have-left-if-we-stop-loving-summer-heatwaves-crush-france-s-season-of-insouciance_6756479_114.html', 'The heatwave continues across France, with nearly the entire country under an orange alert on Thursday. The recurrence of extreme temperatures has taken a toll on morale, dampening the usual carefree spirit of summer, as residents of Le Perreux and Nogent-sur-Marne, in the Paris region, explained.', 'https://img.lemde.fr/2026/08/12/500/0/3000/1500/644/322/60/0/8429c7a_upload-1-kcvbmslgqa8x-canicule-asurp-107913.jpg', '2026-08-13T18:00:09+00:00', '2026-08-13T22:53:11.413721'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (322766, 13880, 'Le Monde', 'en', 'High temperatures continue to put pressure on France''s nuclear power plants', 'https://www.lemonde.fr/en/economy/article/2026/08/13/high-temperatures-continue-to-put-pressure-on-france-s-nuclear-power-plants_6756482_19.html', 'Six EDF nuclear reactors were shut down on Thursday, August 13, due to the ongoing heatwave. As a result, nearly 20% of the nation''s nuclear fleet was unavailable.', 'https://img.lemde.fr/2026/08/13/438/0/4787/2393/644/322/60/0/90fe58d_upload-1-mnyzedqjc8rk-000-c42h7ku.jpg', '2026-08-13T21:39:47+00:00', '2026-08-13T22:53:11.423403'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
