INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (325999, 13904, 'The Guardian', 'en', 'Australia has been galvanised by ‘melon-gate’. So what is the luxury fruit at the centre of the PM’s controversy?', 'https://www.theguardian.com/australia-news/2026/aug/14/australia-albanese-melon-gate-japan-controversy-explained', 'Shizuoka Crown melons are part of an important cultural gifting practice in Japan, where they are hand-patted by growers to achieve an even shape and texture The melons at the centre of a national imbroglio involving the Australian prime minister have the sweetness of a watermelon, the snap of a honeydew and the perfume of a peach, according to fruit sellers. Anthony Albanese maintains he has nothing to apologise for, after a joke he made regarding a gift he received from Japan’s prime minister. Continue reading...', 'https://i.guim.co.uk/img/media/b82943bc7f4f9bf7d7c65771dca146e7c2fac8bf/30_623_2185_1748/master/2185.jpg?width=140&quality=85&auto=format&fit=max&s=6556f93be18d8e7c12408f7aca3c2be3', '2026-08-14T00:58:48+00:00', '2026-08-14T01:10:18.800910'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (308204, 13907, 'The New York Times', 'en', 'Trump Tariffs Force Some Canadian Companies to Move South of the Border', 'https://www.nytimes.com/2026/08/12/world/canada/canada-tariffs-manufacturing-trade-trump.html', 'If President Trump moves ahead with 50 percent tariffs on a wide range of Canadian products later this month, some companies may only survive by relocating to the United States.', 'https://static01.nyt.com/images/2026/08/11/world/00int-canada-tariffs/00int-canada-tariffs-mediumSquareAt3X.jpg', '2026-08-12T12:43:24+00:00', '2026-08-12T22:52:43.075553'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (310031, 13907, 'South China Morning Post', 'en', 'Will Trump’s proposed drug tariffs end India’s reign as ‘pharmacy of the world’?', 'https://www.scmp.com/week-asia/economics/article/3363805/will-trumps-proposed-drug-tariffs-end-indias-reign-pharmacy-world', 'India’s long-held status as the “pharmacy of the world” could be affected by US President Donald Trump’s plan to impose steep tariffs on imported drugs from 2028, threatening the low-cost, export-driven model that has made the country a vital supplier of generic medicines, analysts have warned. Late last month, Trump announced that the US would impose 100 per cent tariffs on generic medicines from August 2028 and increase them to 200 per cent after one year, signalling a major push to bring more...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/12/5ced1fb4-135e-4894-8e27-ca9de6d4a268_69806b87.jpg?itok=0mbKcAvE&v=1786534827', '2026-08-12T11:40:28+00:00', '2026-08-12T22:56:38.329930'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
