INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (324000, 13907, 'South China Morning Post', 'en', 'US accuses Chinese exporters of masterminding ‘Great Transshipment Scam’', 'https://www.scmp.com/news/us/article/3363925/us-accuses-chinese-exporters-masterminding-great-transshipment-scam', 'The Trump administration on Thursday released a sharply worded report accusing Chinese exporters of orchestrating a system of “illegal transshipment” through more than 40 third countries to dodge US tariffs, branding the practice “The Great Transshipment Scam”. The 25-page document claims Chinese firms have systematically diverted goods through lower-tariff jurisdictions since the US kicked off its trade war with China in 2018. It alleges that exporters use limited assembly, relabelling,...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/e6a6836d-f1ea-4814-aad7-fa44a82155bd_dd693149.jpg?itok=HpnSeIGN&v=1786617906', '2026-08-13T10:45:16+00:00', '2026-08-13T22:55:10.936913'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
