INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (325178, 13907, 'South China Morning Post', 'en', 'US accuses 9 Latin American countries of helping China avoid Trump’s tariffs', 'https://www.scmp.com/news/china/diplomacy/article/3363963/us-accuses-9-latin-american-countries-helping-china-avoid-trumps-tariffs', 'Three Latin American governments that moved against Chinese commercial interests over the past year were named in a White House report on Thursday, which accused Chinese exporters of routing goods through third countries to evade US tariffs. Mexico, Panama and Colombia now join Brazil, Argentina, Chile, Peru, Costa Rica and the Dominican Republic among more than 40 countries the report says carry elevated risk of illegal transshipment, the practice of moving goods through an intermediate country...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/14/7859b9ef-8b26-4e78-9dcb-18c4892234d9_9d9ec44e.jpg?itok=e5nuxFsO&v=1786663193', '2026-08-13T23:20:03+00:00', '2026-08-13T23:41:58.602874'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
