INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (310006, 13914, 'South China Morning Post', 'en', 'Trump spokeswoman Karoline Leavitt to step down', 'https://www.scmp.com/news/world/united-states-canada/article/3363831/trump-spokeswoman-karoline-leavitt-step-down', 'White House Press Secretary Karoline Leavitt, the youngest person to hold the role, will leave at month’s end, President Donald Trump announced Wednesday. Leavitt, 28, just recently returned to the White House after taking a brief leave for the birth of her second child in May. Leavitt has been one of the most visible advocates of Trump’s “Make America Great Again” movement. The Republican president described her as one of his “most trusted aides” in a social media post announcing her...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/13/a81b3172-c621-41e7-a9ec-4c15cbadc1bc_7533b335.jpg?itok=G4SV9Ku9&v=1786568590', '2026-08-12T21:03:22+00:00', '2026-08-12T22:56:37.969312'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
