INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (317349, 13914, 'Aaj Tak', 'hi', 'व्हाइट हाउस का ग्लैमरस फेस, 28 की उम्र में हुईं रिटायर!', 'https://www.aajtak.in/trending/story/caroline-leavitt-resigns-trump-white-house-press-secretary-biography-tstsd-dskc-2621199-2026-08-13', 'अमेरिका के राष्ट्रपति डोनाल्ड ट्रंप की प्रेस सचिव कैरोलिन लेविट ने इस्तीफा दे दिया है. ट्रंप ने खुद सोशल मीडिया पर एक पोस्ट शेयर कर इस बात की जानकारी दी. लेविट व्हाइट हाउस की अब तक की सबसे यंग प्रेस सचिव रही हैं. ऐसे में जानते हैं कौन हैं कैरोलिन लेविट और कैसे वह यहां तक पहुंची.', '', '2026-08-13T07:52:45+00:00', '2026-08-13T08:12:38.886734'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
